values
  ('37d57c8c-b58e-475c-9c5d-cb0cb187409e', '77df0463-0315-46d7-8dd7-400359ac5528', null, 'topic'::public.curated_course_node_type, 'Tissue Engineering and Regenerative Medicine Foundations', 'Students begin with the field''s core design logic: combine cells, materials, biochemical signals, and physical cues to repair, replace, or regenerate tissue function.', 0),
  ('5df78dd0-3513-4baf-9136-c325d772adc2', '77df0463-0315-46d7-8dd7-400359ac5528', '37d57c8c-b58e-475c-9c5d-cb0cb187409e', 'subtopic'::public.curated_course_node_type, 'Field overview', 'The point is to understand tissue engineering as an integration of biology, materials science, and engineering design.', 0),
  ('f7c346ea-6749-4f49-9488-5d7db26ead46', '77df0463-0315-46d7-8dd7-400359ac5528', '5df78dd0-3513-4baf-9136-c325d772adc2', 'concept'::public.curated_course_node_type, 'Cells, scaffolds, signals, and bioreactors', null, 0),
