  ('b6f1162a-a3e4-4304-8338-8aa6a5d7913d', '77df0463-0315-46d7-8dd7-400359ac5528', '5df78dd0-3513-4baf-9136-c325d772adc2', 'concept'::public.curated_course_node_type, 'In vitro models and therapeutic constructs', null, 2),
  ('042adaa8-5960-41e2-9422-64225c4dcf51', '77df0463-0315-46d7-8dd7-400359ac5528', '37d57c8c-b58e-475c-9c5d-cb0cb187409e', 'subtopic'::public.curated_course_node_type, 'Design constraints', 'Students learn why engineered tissues must satisfy biological, mechanical, transport, and manufacturing constraints at once.', 1),
  ('9d798d18-a878-4960-986e-6815ca732639', '77df0463-0315-46d7-8dd7-400359ac5528', '042adaa8-5960-41e2-9422-64225c4dcf51', 'concept'::public.curated_course_node_type, 'Target tissue function', null, 0),
