  ('4b72dbe6-bfd3-46fe-83ea-f5f7c4d09186', '77df0463-0315-46d7-8dd7-400359ac5528', 'b019fe0c-ac26-4662-82c5-cc9756319340', 'concept'::public.curated_course_node_type, 'Regenerative medicine milestones', null, 1),
  ('4e5c6bfd-8d37-4ad5-9430-87e64f12c1d5', '77df0463-0315-46d7-8dd7-400359ac5528', 'b019fe0c-ac26-4662-82c5-cc9756319340', 'concept'::public.curated_course_node_type, 'Common barriers to clinical adoption', null, 2),
  ('ef026edd-6efc-46b9-b849-b5b70ea4018b', '77df0463-0315-46d7-8dd7-400359ac5528', null, 'topic'::public.curated_course_node_type, 'Cell Sources and Stem-Cell Biology', 'This module examines where therapeutic or experimental cells come from and how their phenotype, potency, and culture conditions shape tissue-engineered constructs.', 1),
