  ('be1e881e-18c8-42c3-b25d-36e50885ecfd', '77df0463-0315-46d7-8dd7-400359ac5528', 'ef026edd-6efc-46b9-b849-b5b70ea4018b', 'subtopic'::public.curated_course_node_type, 'Stem-cell potency and differentiation', 'Stem cells are useful because they can self-renew and produce specialized cells under the right cues.', 1),
