  ('a7e65647-c9ca-44db-b5a2-e0e24357e8ae', '77df0463-0315-46d7-8dd7-400359ac5528', '8e1ac129-1fb7-478c-9c8f-54ba54e20ff7', 'concept'::public.curated_course_node_type, 'Passage number, viability, and phenotype', null, 2),
  ('767dab15-16ca-4bcf-95ff-2c8593c36543', '77df0463-0315-46d7-8dd7-400359ac5528', null, 'topic'::public.curated_course_node_type, 'Extracellular Matrix Structure and Function', 'Students learn how native ECM provides biochemical, mechanical, and architectural cues that guide tissue development and repair.', 2),
