  ('161b1b0d-3c63-4f86-9c73-8c9b4ded7920', '77df0463-0315-46d7-8dd7-400359ac5528', null, 'topic'::public.curated_course_node_type, 'Scaffold Materials and Fabrication', 'This topic focuses on designing material environments that support cell attachment, organization, growth, degradation, and tissue formation.', 3),
