  ('816819ee-d24c-489a-bd65-d6fd154ac50f', '77df0463-0315-46d7-8dd7-400359ac5528', null, 'topic'::public.curated_course_node_type, 'Vascularization and Mass-Transport Limits', 'This topic addresses one of tissue engineering''s central bottlenecks: keeping cells alive and functional in thick or metabolically active constructs.', 7),
