  ('9563f1cd-b0c3-4c2b-8054-ec5aeb1461ef', '77df0463-0315-46d7-8dd7-400359ac5528', null, 'topic'::public.curated_course_node_type, 'Tissue Characterization, Imaging, and Functional Testing', 'Students learn how engineered tissues are evaluated using structural, biochemical, mechanical, and biological assays.', 8),
