  ('481ea9e3-e77c-4e9f-a7b8-365989e7d080', '77df0463-0315-46d7-8dd7-400359ac5528', null, 'topic'::public.curated_course_node_type, 'Tissue-Specific Engineering Applications', 'This module compares strategies for bone, cartilage, skin, vascular, cardiac, neural, and organoid systems.', 9),
