  ('8588e66a-c9d2-4e26-8d63-b4a062c1ae3a', '77df0463-0315-46d7-8dd7-400359ac5528', 'dea8dc4b-aee8-4885-9a29-481e877a2072', 'concept'::public.curated_course_node_type, 'Immune rejection', null, 0),
