  ('33c89714-d000-49cd-a8a3-6dcb0919f54c', '77df0463-0315-46d7-8dd7-400359ac5528', '88dbc816-e3c1-4161-a25d-e717326d0db3', 'concept'::public.curated_course_node_type, 'GMP Concepts', null, 0),
